const fs = require('fs');
const staticData = $getWorkflowStaticData('global');

const promptsPath = $env.NAIRA_PROMPTS_JSON_PATH || '/data/naira_test_prompts.json';
const logPath = $env.NAIRA_LOG_PATH || '/var/log/naira/naira.log';

// Load the 100-prompt dataset
const prompts = JSON.parse(fs.readFileSync(promptsPath, 'utf-8'));

// Establish a log baseline so we ONLY look at NEW log lines written
// during this test run, not historical noise from previous sessions.
let baselineLineCount = 0;
try {
  const existingLog = fs.readFileSync(logPath, 'utf-8');
  baselineLineCount = existingLog.split('\n').length;
} catch (e) {
  baselineLineCount = 0; // log file doesn't exist yet, that's fine
}

staticData.lastLineCount = baselineLineCount;
staticData.allResults = [];
staticData.logPath = logPath;
staticData.runStartedAt = new Date().toISOString();

return prompts.map(p => ({ json: p }));

const item = $input.item.json;

return {
  json: {
    id: item.id,
    prompt: item.prompt,
    expected_engine: item.expected_engine,
    module: item.module,
    memory_event: item.memory_event,
    request_body: {
      text: item.prompt,
      session_id: 'n8n_test'
    }
  }
};

const fs = require('fs');
const staticData = $getWorkflowStaticData('global');

// ---- 1. Read only the NEW lines written since the last check ----
let fullLogText = '';
try {
  fullLogText = fs.readFileSync(staticData.logPath, 'utf-8');
} catch (e) {
  fullLogText = '';
}
const allLines = fullLogText.split('\n');
const newLines = allLines.slice(staticData.lastLineCount);
staticData.lastLineCount = allLines.length;
const logChunk = newLines.join('\n');

// ---- 2. Regex signatures for what actually happened under the hood ----
const patterns = {
  heavyLLM:     /Routed to Heavy LLM|AutonomousTaskEngine|ReAct loop|DecisionManager.*HEAVY/i,
  fcr:          /\[FCR\]|FastCommandRouter|Routed to FCR|DecisionManager.*FCR/i,
  pythonExec:   /Executed python script|execute_local_python|Subprocess launched/i,
  fileOp:       /File created|File deleted|File renamed|file_manager.*success/i,
  gitOp:        /git_handler|Git command executed/i,
  memoryEvent:  /Background memory harvest|MemoryHarvester|ContextBuilder.*inject/i,
  errorTrace:   /Traceback \(most recent call last\)|ERROR|Exception raised/i
};

// ---- 3. Did the previous HTTP call actually error out? ----
const originalData = $('Build Chat Payload').item.json;
const apiResponse   = $('Call Naira Chat API').item.json;
const httpFailed = !!(apiResponse && apiResponse.error);

let actualEngine = 'UNKNOWN - no routing log found';
if (patterns.heavyLLM.test(logChunk)) actualEngine = 'Heavy LLM';
else if (patterns.fcr.test(logChunk)) actualEngine = 'FCR';

let executionStatus;
if (httpFailed) {
  executionStatus = `Failed: HTTP request error - ${apiResponse.error}`;
  actualEngine = 'N/A (request failed)';
} else if (patterns.errorTrace.test(logChunk)) {
  const match = logChunk.match(patterns.errorTrace);
  executionStatus = `Failed: Error found in logs (${match[0]})`;
} else if (patterns.pythonExec.test(logChunk)) {
  executionStatus = 'Verified: Subprocess launched successfully';
} else if (patterns.fileOp.test(logChunk)) {
  executionStatus = 'Verified: File operation confirmed';
} else if (patterns.gitOp.test(logChunk)) {
  executionStatus = 'Verified: Git command executed';
} else if (actualEngine === 'FCR') {
  executionStatus = 'Verified: FCR handler dispatched (no subprocess expected)';
} else {
  executionStatus = 'Failed: No execution log found';
}

// ---- 4. Pull the reply text out of whatever shape /api/chat returns ----
const reply = apiResponse && !httpFailed
  ? (apiResponse.reply || apiResponse.response || apiResponse.message || JSON.stringify(apiResponse))
  : 'NO REPLY RECEIVED';

// ---- 5. Build the exact report row and stash it in static data ----
const row = {
  'Prompt': originalData.prompt,
  'Expected Engine': originalData.expected_engine,
  'Actual Engine Triggered': actualEngine,
  "Naira's Reply": reply,
  'Real-World Execution Status': executionStatus,
  '_test_id': originalData.id,
  '_module_tested': originalData.module,
  '_memory_event': originalData.memory_event,
  '_raw_log_chunk': logChunk
};

staticData.allResults.push(row);

return [{ json: row }];

const fs = require('fs');
const staticData = $getWorkflowStaticData('global');
const results = staticData.allResults || [];

// Also persist a raw JSON report alongside the CSV, since the
// requirement allows CSV, JSON, or Google Sheet output.
const jsonReportPath = $env.NAIRA_REPORT_JSON_PATH || '/data/naira_test_report.json';
try {
  fs.writeFileSync(jsonReportPath, JSON.stringify({
    run_started_at: staticData.runStartedAt,
    run_finished_at: new Date().toISOString(),
    total_tests: results.length,
    results
  }, null, 2), 'utf-8');
} catch (e) {
  // non-fatal - CSV export below still proceeds
}

return results.map(r => ({ json: r }));
